"""Build versioned consumer contracts. Does not change historical OpenBread files."""
import json
from pathlib import Path

from common import ROOT, OUT, save

def obj(properties,required=None):
    return {'type':'object','properties':properties,'required':list(properties) if required is None else required,'additionalProperties':False}
def nullable(value):return {'anyOf':[value,{'type':'null'}]}
string=lambda maximum:{'type':'string','maxLength':maximum}
allergens=['gluten','crustaceans','eggs','fish','peanuts','soy','milk','nuts','celery','mustard','sesame','sulphites','lupin','molluscs']
alist={'type':'array','maxItems':14,'uniqueItems':True,'items':{'enum':allergens}}
nutrients=['energy_kj','energy_kcal','fat_g','saturates_g','carbohydrate_g','sugars_g','polyols_g','fibre_g','protein_g','salt_g']
portion=obj({'amount':{'type':'number','exclusiveMinimum':0,'maximum':100000},'unit':{'enum':['g','ml']}})
unknown_nutrition=obj({'status':{'const':'unknown'},'basis':{'type':'null'},'preparation':{'type':'null'},'jurisdiction':{'type':'null'},'values':{'type':'null'},'portion':{'type':'null'}})
declared_nutrition=obj({'status':{'const':'declared'},'basis':{'enum':['per_100_g','per_100_ml','per_portion']},'preparation':{'enum':['as_sold','as_prepared']},'jurisdiction':{'enum':['EU','US','other']},'values':{**obj({k:{'type':'number','minimum':0,'maximum':100000} for k in nutrients},[]),'minProperties':1},'portion':nullable(portion)},['status','basis','preparation','jurisdiction','values'])
food={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'OpenAliment structured food data v1',**obj({'schema_version':{'const':'openaliment.food.v1'},'allergens':obj({'status':{'enum':['unknown','declared']},'contains':alist,'may_contain':alist}), 'nutrition':{'oneOf':[unknown_nutrition,declared_nutrition]},'after_opening':nullable(obj({'hours':{'type':'integer','minimum':1,'maximum':8760},'conditions':{**string(500),'minLength':1}}))},['schema_version'])}
food['description']='Only explicit producer declarations. Text and historical labels remain intact. Runtime additionally validates status, units, relationships and numeric bounds. Publication is a separate approval.'
save('food-data.schema.json',food)
date={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'OpenAliment date with precision v1',**obj({'kind':{'enum':['use_by','best_before','reminder']},'value':{'type':'string','pattern':'^[0-9]{4}(-[0-9]{2}(-[0-9]{2})?)?$'},'precision':{'enum':['day','month','year']},'source':{'enum':['producer','barcode','user','receipt']},'raw':string(80)},['kind','value','precision','source'])}
date['description']='Runtime verifies calendar validity and precision. GS1 day 00 preserves month precision and is interpreted as month end. Reminder is never an expiry declaration.'
save('food-date.schema.json',date)
profile={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'OpenAliment public consumer product v1','type':'object','required':['schema_version','name','food_data','expiry','alerts','alerts_checked_at','source','simulation'],'properties':{'schema_version':{'const':'openaliment.consumer-product.v1'},'name':string(180),'food_data':{'$ref':'food-data.schema.json'},'expiry':nullable({'$ref':'food-date.schema.json'}),'alerts':{'type':'array','items':{'type':'object'}},'alerts_checked_at':{'type':['string','null']},'source':{'type':'object'},'simulation':{'type':'boolean'}},'additionalProperties':True}
profile['properties']['gs1_qualifiers']=nullable(obj({ai:{'type':'string','minLength':1,'maxLength':28 if ai=='235' else 20} for ai in ['22','10','21','235']},[]))
profile['properties']['gs1_qualifiers']['description']='Observed GS1 key qualifiers, decoded exactly once; not a producer approval or proof of purchase. TPX is exclusive; serial + lot + CPV are permitted in a request URI.'
save('consumer-product-profile.schema.json',profile)
inventory={'$schema':'https://json-schema.org/draft/2020-12/schema','title':'OpenAliment personal inventory v1','type':'object','required':['schema_version','items','events','preferences','shopping'],'properties':{'schema_version':{'const':'openaliment.home.v1'},'items':{'type':'array','maxItems':2000,'items':{'type':'object','required':['id','revision','profile','state','expiry'],'properties':{'id':{'type':'string','pattern':'^[a-f0-9]{32}$'},'revision':{'type':'integer','minimum':1},'profile':{'$ref':'consumer-product-profile.schema.json'},'state':{'enum':['available','consumed']},'expiry':nullable({'$ref':'food-date.schema.json'})}}},'events':{'type':'array','maxItems':50000,'items':{'type':'object'}},'preferences':obj({'allergens':alist}),'shopping':{'type':'array','maxItems':500,'items':{'type':'object'}}},'additionalProperties':False}
save('consumer-inventory.schema.json',inventory)
save('consumer-transfer.schema.json',{'$schema':'https://json-schema.org/draft/2020-12/schema','title':'OpenAliment personal transfer v1',**obj({'schema_version':{'const':'openaliment.home.transfer.v1'},'exported_at':{'type':'string','format':'date-time'},'data':obj({'inventory':{'$ref':'consumer-inventory.schema.json'},'photos':{'type':'array','maxItems':5000,'items':obj({'id':{'type':'string','pattern':'^[a-f0-9]{32}$'},'mime':{'const':'image/jpeg'},'sha256':{'type':'string','pattern':'^[a-f0-9]{64}$'},'content_base64':string(1400000)})}}),'data_sha256':{'type':'string','pattern':'^[a-f0-9]{64}$'}})})
save('consumer-openapi.json',{'openapi':'3.1.0','info':{'title':'OpenAliment — API public pentru alimente','version':'2.0.0','description':'Informații alimentare publicate și aprobate, identificare de produs și lot și alerte curente. Aceste operații nu accesează rețete private, inventare personale sau preferințe de sănătate.'},'servers':[{'url':'https://openaliment.ro'}],'paths':{'/api/v2/public/food':{'get':{'summary':'Read the approved projection for a barcode, native page or GS1 Digital Link','parameters':[{'name':'code','in':'query','required':True,'schema':{'type':'string','maxLength':4096}}],'responses':{'200':{'description':'Public approved data, or explicit unavailable fields','content':{'application/json':{'schema':{'$ref':'/api/schemas/consumer-product-profile.schema.json'}}}},'400':{'description':'Invalid URI syntax'},'404':{'description':'Native object not public'},'422':{'description':'Invalid barcode, date or value'},'503':{'description':'Service unavailable'}}}},'/api/v2/public/capabilities':{'get':{'summary':'Runtime availability of optional consumer capabilities','responses':{'200':{'description':'Capability flags; not a conformance assertion'}}}}}})
print('Built food, date, product, inventory, transfer and consumer API contracts.')
